<?php ob_start();?>
<section class="page-heading"><div><p class="eyebrow">Coordenação</p><h1>Relatório consolidado APC</h1><p>Conferência de planos, devoluções e pendências. Os totais de alunos são atualizados quando a lista da turma é consultada.</p></div><a class="button" href="?<?=e(http_build_query($filters+['formato'=>'csv']))?>">Exportar CSV</a></section>
<form class="card apc-filter-grid" method="get" action="/apc/relatorios"><label>Ano letivo <input type="number" name="ano" min="2000" max="2100" value="<?=e($filters['ano'])?>"></label><label>Evento <select name="evento"><option value="">Todos</option><?php foreach($events as$event):?><option value="<?=e($event['id'])?>" <?=$filters['evento']==$event['id']?'selected':''?>><?=e(date('d/m/Y',strtotime($event['data'])).' · '.$event['titulo'])?></option><?php endforeach;?></select></label><label>Turma <select name="turma"><option value="">Todas</option><?php foreach($classes as$class):?><option value="<?=e($class['id'])?>" <?=$filters['turma']==$class['id']?'selected':''?>><?=e($class['nome'])?></option><?php endforeach;?></select></label><label>Professor <select name="professor"><option value="">Todos</option><?php foreach($professors as$id=>$name):?><option value="<?=e($id)?>" <?=$filters['professor']==$id?'selected':''?>><?=e($name)?></option><?php endforeach;?></select></label><label>Status <select name="status"><option value="">Todos</option><option value="RASCUNHO" <?=$filters['status']==='RASCUNHO'?'selected':''?>>Rascunho</option><option value="FINALIZADO" <?=$filters['status']==='FINALIZADO'?'selected':''?>>Finalizado</option></select></label><div class="actions"><a class="button" href="/apc/relatorios">Limpar</a><button class="primary">Filtrar</button></div></form>
<section class="card"><div class="table"><table><thead><tr><th>APC</th><th>Professor</th><th>Turma</th><th>Componente</th><th>Status</th><th>Alunos</th><th>Entregues</th><th>Não entregues</th><th>Percentual</th><th>Ação</th></tr></thead><tbody><?php foreach($rows as$row):$total=$row['total_alunos_snapshot'];$delivered=(int)$row['entregues'];$missing=$total===null?null:max(0,(int)$total-$delivered);$percent=$total?round($delivered/(int)$total*100,1):null;?><tr><td><strong><?=e(date('d/m/Y',strtotime($row['evento_data'])))?></strong><small><?=e($row['evento_titulo'])?></small></td><td><?=e($row['professor_nome_snapshot'])?></td><td><?=e($row['turma_nome_snapshot'])?></td><td><?=e($row['componente_curricular'])?></td><td><span class="badge status-<?=e(strtolower($row['status']))?>"><?=e($row['status'])?></span></td><td><?=e($total??'—')?></td><td><?=e($delivered)?></td><td><?=e($missing??'—')?></td><td><?=e($percent===null?'—':number_format($percent,1,',','.').'%')?></td><td><a class="button small-button" href="/apc/planos/<?=e($row['id'])?>">Consultar</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="empty-state"><p>Nenhum plano corresponde aos filtros.</p></div><?php endif;?></section>
